-- The data dictionary: a description of every schema, table, view, column and function.
--
-- The descriptions live in the database (COMMENT ON), next to what they describe, and
-- docs/data-dictionary.md is generated from them (make dictionary). A test fails when a table,
-- view, column or function has none, so every later migration documents what it adds. A column of
-- a view that only passes a column of a table on takes the description of that column.

COMMENT ON SCHEMA meta IS 'The catalogue: sources, their snapshots, pipeline runs, migrations and exit-check reports.';
COMMENT ON SCHEMA raw IS 'Data exactly as delivered, one row per feature per loaded snapshot, in the coordinate system of the delivery.';
COMMENT ON SCHEMA staging IS 'Cleaned, typed, reprojected (EPSG:25832) data with history: one row per version of a feature.';
COMMENT ON SCHEMA core IS 'Derived layers that routing may use, rebuilt from staging and from recorded human decisions.';
COMMENT ON SCHEMA results IS 'Results of the routing phases (cost surfaces, routes); empty until those phases exist.';

-- meta
COMMENT ON TABLE meta.schema_migration IS 'The migrations applied to this database, with the checksum of each file.';
COMMENT ON COLUMN meta.schema_migration.version IS 'Number of the migration, the prefix of its file name.';
COMMENT ON COLUMN meta.schema_migration.name IS 'Name of the migration file without the number and the extension.';
COMMENT ON COLUMN meta.schema_migration.checksum IS 'SHA-256 of the file as applied; a later change of the file is refused.';
COMMENT ON COLUMN meta.schema_migration.applied_at IS 'When the migration was applied.';
COMMENT ON COLUMN meta.source.source_id IS 'Identifier of the source (lower case, digits, underscore), the name of its file in config/sources.';
COMMENT ON COLUMN meta.source.title IS 'Human-readable name of the data set.';
COMMENT ON COLUMN meta.source.publisher IS 'Organisation that publishes the data.';
COMMENT ON COLUMN meta.source.licence_id IS 'Short identifier of the licence, for example dl-de-by-2.0 or ODbL-1.0.';
COMMENT ON COLUMN meta.source.licence_url IS 'Address of the licence text.';
COMMENT ON COLUMN meta.source.attribution IS 'The credit line that every map or export using the data must print.';
COMMENT ON COLUMN meta.source.homepage IS 'Address of the page that describes the data set; NULL when there is none.';
COMMENT ON COLUMN meta.source.created_at IS 'When the source was first registered.';
COMMENT ON COLUMN meta.source_version.version_id IS 'Identifier of the snapshot; it grows with time within a source, so it orders the history.';
COMMENT ON COLUMN meta.source_version.source_id IS 'The source the snapshot belongs to.';
COMMENT ON COLUMN meta.source_version.remote_url IS 'The address the snapshot was fetched from, after redirects.';
COMMENT ON COLUMN meta.source_version.remote_etag IS 'ETag header of the remote file at fetch time; NULL when the server sent none.';
COMMENT ON COLUMN meta.source_version.remote_last_modified IS 'Last-Modified header of the remote file at fetch time; NULL when the server sent none.';
COMMENT ON COLUMN meta.source_version.content_length IS 'Size of the file in bytes.';
COMMENT ON COLUMN meta.source_version.sha256 IS 'SHA-256 of the stored file; NULL until the file is fetched.';
COMMENT ON COLUMN meta.source_version.local_path IS 'Where the file is stored, relative to the raw data folder of the environment.';
COMMENT ON COLUMN meta.source_version.status IS 'discovered, fetched, loaded, diffed, applied, failed or quarantined (applied, but the validation found an error).';
COMMENT ON COLUMN meta.source_version.created_at IS 'When the snapshot was recorded.';
COMMENT ON COLUMN meta.pipeline_run.run_id IS 'Identifier of the run.';
COMMENT ON COLUMN meta.pipeline_run.stage IS 'check, fetch, load, diff, apply, validate, verify or catalogue.';
COMMENT ON COLUMN meta.pipeline_run.source_id IS 'The source the stage ran for.';
COMMENT ON COLUMN meta.pipeline_run.version_id IS 'The snapshot the stage worked on; NULL for a stage that works without one (check, catalogue, verify, a fetch that found nothing new).';
COMMENT ON COLUMN meta.pipeline_run.started_at IS 'When the stage started.';
COMMENT ON COLUMN meta.pipeline_run.finished_at IS 'When the stage ended; NULL while it runs or when it was interrupted.';
COMMENT ON COLUMN meta.pipeline_run.status IS 'running, succeeded or failed.';
COMMENT ON COLUMN meta.pipeline_run.result IS 'The structured result of the stage (counts, decisions), as printed with --json.';
COMMENT ON COLUMN meta.pipeline_run.error IS 'The error message of a failed stage; NULL otherwise.';
COMMENT ON COLUMN meta.tile.source_id IS 'The index-based source the tile belongs to.';
COMMENT ON COLUMN meta.tile.name IS 'File name of the tile as listed in the index.';
COMMENT ON COLUMN meta.tile.remote_timestamp IS 'Time of the tile in the index; a new time is a new version of the tile.';
COMMENT ON COLUMN meta.tile.size IS 'Size of the tile file in bytes.';
COMMENT ON COLUMN meta.tile.sha256 IS 'SHA-256 of the stored tile file.';
COMMENT ON COLUMN meta.tile.local_path IS 'Where the tile file is stored, relative to the raw data folder of the environment.';
COMMENT ON COLUMN meta.tile.status IS 'fetched (the newest version), superseded (an older one), removed (left the index) or corrupt (failed verification).';
COMMENT ON COLUMN meta.tile.fetched_at IS 'When the tile was fetched.';
COMMENT ON COLUMN meta.check_run.check_run_id IS 'Identifier of the run of the exit check.';
COMMENT ON COLUMN meta.check_run.outcome IS 'passed (no error) or failed (at least one error).';
COMMENT ON COLUMN meta.check_run.errors IS 'Number of results with severity error.';
COMMENT ON COLUMN meta.check_run.warnings IS 'Number of results with severity warning.';
COMMENT ON COLUMN meta.check_run.options IS 'How the check ran: validity, files, partial (the validity scan was skipped) and the isolation level.';
COMMENT ON COLUMN meta.check_run.created_at IS 'When the report was stored.';
COMMENT ON COLUMN meta.check_result.check_result_id IS 'Identifier of the result.';
COMMENT ON COLUMN meta.check_result.check_run_id IS 'The run the result belongs to.';
COMMENT ON COLUMN meta.check_result.layer IS 'The layer that was checked, for example parcel or wind_unit.';
COMMENT ON COLUMN meta.check_result.source_id IS 'The source within the layer; - for a result about the whole layer.';
COMMENT ON COLUMN meta.check_result.check_name IS 'Name of the check, for example geometry_invalid, or flag:<name> for a quality flag.';
COMMENT ON COLUMN meta.check_result.bad IS 'Number of rows (or sources, for a source-level check) that failed the check.';
COMMENT ON COLUMN meta.check_result.total IS 'Number of rows (or 1, for a source-level check) that were checked.';
COMMENT ON COLUMN meta.check_result.message IS 'What was found, in words; empty when nothing was found.';
COMMENT ON VIEW meta.check_result_current IS 'The results of the newest run of the exit check.';
COMMENT ON COLUMN meta.check_result_current.check_run_id IS 'The run the result belongs to: always the newest one.';

-- raw
COMMENT ON COLUMN raw.osm_object.version_id IS 'The snapshot the object was loaded from.';
COMMENT ON COLUMN raw.osm_object.layer IS 'GDAL layer of the object: points (nodes), lines (ways) or multipolygons (closed ways and relations).';
COMMENT ON COLUMN raw.osm_object.osm_key IS 'n<id>, w<id> or r<id>: the OSM type and id, stable across snapshots.';
COMMENT ON COLUMN raw.osm_object.osm_version IS 'The version number OSM gives the object; it grows with every edit.';
COMMENT ON COLUMN raw.osm_object.osm_timestamp IS 'When the object was last edited in OSM.';
COMMENT ON COLUMN raw.osm_object.name IS 'OSM tag name.';
COMMENT ON COLUMN raw.osm_object.ref IS 'OSM tag ref (a reference number of the operator).';
COMMENT ON COLUMN raw.osm_object.operator IS 'OSM tag operator.';
COMMENT ON COLUMN raw.osm_object.power IS 'OSM tag power (substation, line, cable, generator, tower, ...).';
COMMENT ON COLUMN raw.osm_object.voltage IS 'OSM tag voltage as written, in volts, several values separated by semicolons.';
COMMENT ON COLUMN raw.osm_object.cables IS 'OSM tag cables (number of conductors).';
COMMENT ON COLUMN raw.osm_object.circuits IS 'OSM tag circuits (number of circuits).';
COMMENT ON COLUMN raw.osm_object.generator_source IS 'OSM tag generator:source (wind, solar, ...).';
COMMENT ON COLUMN raw.osm_object.generator_method IS 'OSM tag generator:method (wind_turbine, photovoltaic, ...).';
COMMENT ON COLUMN raw.osm_object.generator_output_electricity IS 'OSM tag generator:output:electricity as written (3 MW, 600 kW, yes, ...).';
COMMENT ON COLUMN raw.osm_object.highway IS 'OSM tag highway.';
COMMENT ON COLUMN raw.osm_object.railway IS 'OSM tag railway.';
COMMENT ON COLUMN raw.osm_object.waterway IS 'OSM tag waterway.';
COMMENT ON COLUMN raw.osm_object."natural" IS 'OSM tag natural.';
COMMENT ON COLUMN raw.osm_object.landuse IS 'OSM tag landuse.';
COMMENT ON COLUMN raw.osm_object.building IS 'OSM tag building.';
COMMENT ON COLUMN raw.osm_object.geom IS 'Geometry as delivered, in WGS 84 (EPSG:4326).';
COMMENT ON COLUMN raw.osm_change.version_id IS 'The snapshot that brought the change.';
COMMENT ON COLUMN raw.osm_change.previous_version_id IS 'The snapshot it is compared with; NULL for the first snapshot of a source.';
COMMENT ON COLUMN raw.osm_change.layer IS 'GDAL layer of the object: points, lines or multipolygons.';
COMMENT ON COLUMN raw.osm_change.osm_key IS 'n<id>, w<id> or r<id> of the object.';
COMMENT ON COLUMN raw.osm_change.change IS 'added, changed or removed.';
COMMENT ON COLUMN raw.osm_change.old_osm_version IS 'OSM version of the object in the previous snapshot; NULL when it was added.';
COMMENT ON COLUMN raw.osm_change.new_osm_version IS 'OSM version of the object in this snapshot; NULL when it was removed.';
COMMENT ON COLUMN raw.feature.version_id IS 'The snapshot the feature was loaded from.';
COMMENT ON COLUMN raw.feature.layer IS 'Kind of feature within the source, for example wind_unit, parcel, nature_reserve or catalogue_value.';
COMMENT ON COLUMN raw.feature.feature_key IS 'Identifier of the feature given by the publisher, stable across snapshots where the publisher keeps it.';
COMMENT ON COLUMN raw.feature.attributes IS 'Every attribute as delivered, as text, under the name the publisher uses.';
COMMENT ON COLUMN raw.feature.geom IS 'Geometry as delivered, with the coordinate system of the delivery; NULL when the feature has none.';
COMMENT ON COLUMN raw.feature_change.version_id IS 'The snapshot that brought the change.';
COMMENT ON COLUMN raw.feature_change.previous_version_id IS 'The snapshot it is compared with; NULL for the first snapshot of a source.';
COMMENT ON COLUMN raw.feature_change.layer IS 'Kind of feature within the source.';
COMMENT ON COLUMN raw.feature_change.feature_key IS 'Identifier of the feature given by the publisher.';
COMMENT ON COLUMN raw.feature_change.change IS 'added, changed or removed.';
COMMENT ON COLUMN raw.feature_change.changed_fields IS 'For a changed feature: the attribute names whose value differs, plus geometry; empty otherwise.';

-- staging: OSM power objects
COMMENT ON COLUMN staging.osm_power_feature.feature_id IS 'Identifier of this version of the object.';
COMMENT ON COLUMN staging.osm_power_feature.source_id IS 'The OSM extract the object comes from.';
COMMENT ON COLUMN staging.osm_power_feature.layer IS 'GDAL layer of the object: points, lines or multipolygons.';
COMMENT ON COLUMN staging.osm_power_feature.osm_key IS 'n<id>, w<id> or r<id>: the stable OSM identifier.';
COMMENT ON COLUMN staging.osm_power_feature.valid_from_version_id IS 'The snapshot from which this version of the object holds.';
COMMENT ON COLUMN staging.osm_power_feature.valid_to_version_id IS 'The snapshot that changed or removed the object; NULL while this version is current.';
COMMENT ON COLUMN staging.osm_power_feature.kind IS 'Class derived from the tags: substation, line, cable, minor_line, wind_turbine, generator, support or other.';
COMMENT ON COLUMN staging.osm_power_feature.power IS 'OSM tag power as delivered.';
COMMENT ON COLUMN staging.osm_power_feature.name IS 'OSM tag name.';
COMMENT ON COLUMN staging.osm_power_feature.ref IS 'OSM tag ref.';
COMMENT ON COLUMN staging.osm_power_feature.operator IS 'OSM tag operator.';
COMMENT ON COLUMN staging.osm_power_feature.substation_type IS 'OSM tag substation (transmission, distribution, ...).';
COMMENT ON COLUMN staging.osm_power_feature.voltage_raw IS 'OSM tag voltage as written.';
COMMENT ON COLUMN staging.osm_power_feature.voltage_v IS 'Highest voltage in volts read from voltage_raw; NULL when missing or unreadable.';
COMMENT ON COLUMN staging.osm_power_feature.voltage_class IS 'For substations, lines and cables: extra_high (220 kV and more), high (110 kV and more), medium_low or unknown; NULL for other kinds.';
COMMENT ON COLUMN staging.osm_power_feature.generator_source IS 'OSM tag generator:source.';
COMMENT ON COLUMN staging.osm_power_feature.output_raw IS 'OSM tag generator:output:electricity as written.';
COMMENT ON COLUMN staging.osm_power_feature.output_w IS 'Electrical output in watts read from output_raw; NULL when missing or unreadable.';
COMMENT ON COLUMN staging.osm_power_feature.osm_version IS 'The version number OSM gives the object.';
COMMENT ON COLUMN staging.osm_power_feature.osm_timestamp IS 'When the object was last edited in OSM.';
COMMENT ON COLUMN staging.osm_power_feature.geom IS 'Geometry of the object in EPSG:25832, repaired when it was invalid.';
COMMENT ON VIEW staging.osm_power_current IS 'The current version of every OSM power object.';

-- staging: wind units
COMMENT ON COLUMN staging.wind_unit.unit_id IS 'Identifier of this version of the unit.';
COMMENT ON COLUMN staging.wind_unit.source_id IS 'The register export the unit comes from.';
COMMENT ON COLUMN staging.wind_unit.unit_key IS 'MaStR number of the unit (EinheitMastrNummer), stable across exports.';
COMMENT ON COLUMN staging.wind_unit.valid_from_version_id IS 'The snapshot from which this version of the unit holds.';
COMMENT ON COLUMN staging.wind_unit.valid_to_version_id IS 'The snapshot that changed or removed the unit; NULL while this version is current.';
COMMENT ON COLUMN staging.wind_unit.status_code IS 'Code of the operating status in the register catalogue.';
COMMENT ON COLUMN staging.wind_unit.status IS 'Operating status decoded from the catalogue: In Betrieb, In Planung, Vorübergehend stillgelegt, Endgültig stillgelegt.';
COMMENT ON COLUMN staging.wind_unit.name IS 'Name of the unit as registered.';
COMMENT ON COLUMN staging.wind_unit.wind_farm IS 'Name of the wind farm as registered.';
COMMENT ON COLUMN staging.wind_unit.municipality_key IS 'Official municipality key (AGS, 8 digits) as registered.';
COMMENT ON COLUMN staging.wind_unit.municipality IS 'Name of the municipality as registered.';
COMMENT ON COLUMN staging.wind_unit.district IS 'Name of the district as registered.';
COMMENT ON COLUMN staging.wind_unit.postcode IS 'Postcode as registered.';
COMMENT ON COLUMN staging.wind_unit.manufacturer IS 'Manufacturer of the turbine, decoded from the catalogue.';
COMMENT ON COLUMN staging.wind_unit.type_designation IS 'Type of the turbine as registered.';
COMMENT ON COLUMN staging.wind_unit.location_type IS 'Onshore or offshore, decoded from the catalogue.';
COMMENT ON COLUMN staging.wind_unit.gross_kw IS 'Gross rated power in kilowatts.';
COMMENT ON COLUMN staging.wind_unit.net_kw IS 'Net rated power in kilowatts.';
COMMENT ON COLUMN staging.wind_unit.hub_height_m IS 'Hub height in metres.';
COMMENT ON COLUMN staging.wind_unit.rotor_diameter_m IS 'Rotor diameter in metres.';
COMMENT ON COLUMN staging.wind_unit.commissioned IS 'Date of commissioning; NULL for a unit not yet in operation or an unreadable date.';
COMMENT ON COLUMN staging.wind_unit.planned_commissioning IS 'Planned date of commissioning, for a planned unit.';
COMMENT ON COLUMN staging.wind_unit.decommissioned IS 'Date of final decommissioning, for a retired unit.';
COMMENT ON COLUMN staging.wind_unit.grid_location_key IS 'MaStR number of the location (LokationMastrNummer): the units of one wind farm share it.';
COMMENT ON VIEW staging.wind_unit_current IS 'The current version of every wind unit.';
COMMENT ON TABLE staging.state_box IS 'Coarse WGS 84 boxes of the states, used to flag coordinates in the wrong state; boxes, not borders.';
COMMENT ON COLUMN staging.state_box.state_key IS 'First two digits of the municipality key: 02 Hamburg, 05 Nordrhein-Westfalen, ...';
COMMENT ON COLUMN staging.state_box.name IS 'Name of the state.';
COMMENT ON COLUMN staging.state_box.lon_min IS 'Western edge of the box, degrees east (EPSG:4326).';
COMMENT ON COLUMN staging.state_box.lat_min IS 'Southern edge of the box, degrees north (EPSG:4326).';
COMMENT ON COLUMN staging.state_box.lon_max IS 'Eastern edge of the box, degrees east (EPSG:4326).';
COMMENT ON COLUMN staging.state_box.lat_max IS 'Northern edge of the box, degrees north (EPSG:4326).';

-- staging: land cover and protected areas
COMMENT ON TABLE staging.clc_class IS 'The CORINE legend: the 44 classes of the nomenclature and the three codes for no data.';
COMMENT ON COLUMN staging.clc_class.code IS 'Three-digit CORINE code, for example 211.';
COMMENT ON COLUMN staging.clc_class.name IS 'Name of the class, for example Non-irrigated arable land.';
COMMENT ON COLUMN staging.clc_class.level1 IS 'Group of the first level: Artificial surfaces, Agricultural areas, Forest and semi-natural areas, Wetlands, Water bodies or No data.';
COMMENT ON COLUMN staging.land_cover.land_cover_id IS 'Identifier of this version of the polygon.';
COMMENT ON COLUMN staging.land_cover.source_id IS 'The CORINE release the polygon comes from.';
COMMENT ON COLUMN staging.land_cover.valid_from_version_id IS 'The snapshot from which this version of the polygon holds.';
COMMENT ON COLUMN staging.land_cover.valid_to_version_id IS 'The snapshot that changed or removed the polygon; NULL while this version is current.';
COMMENT ON COLUMN staging.land_cover.clc_code IS 'CORINE code of the polygon; see staging.clc_class.';
COMMENT ON COLUMN staging.land_cover.geom IS 'Outline in EPSG:25832, repaired when it was invalid; NULL when the delivery had none.';
COMMENT ON VIEW staging.land_cover_current IS 'The current land-cover polygons with the name and group of their class.';
COMMENT ON COLUMN staging.land_cover_current.class_name IS 'Name of the CORINE class (staging.clc_class.name); NULL for an unknown code.';
COMMENT ON COLUMN staging.land_cover_current.class_group IS 'First-level group of the class (staging.clc_class.level1); NULL for an unknown code.';
COMMENT ON COLUMN staging.protected_area.protected_area_id IS 'Identifier of this version of the area.';
COMMENT ON COLUMN staging.protected_area.source_id IS 'The BfN data set the area comes from.';
COMMENT ON COLUMN staging.protected_area.feature_key IS 'Identifier of the area given by the BfN.';
COMMENT ON COLUMN staging.protected_area.valid_from_version_id IS 'The snapshot from which this version of the area holds.';
COMMENT ON COLUMN staging.protected_area.valid_to_version_id IS 'The snapshot that changed or removed the area; NULL while this version is current.';
COMMENT ON COLUMN staging.protected_area.kind IS 'nature_reserve, habitat_area (FFH), bird_area (SPA), national_park or landscape_area.';
COMMENT ON COLUMN staging.protected_area.name IS 'Name of the area (NAME).';
COMMENT ON COLUMN staging.protected_area.site_code IS 'Site code of the area (SITECODE), for example the Natura 2000 code.';
COMMENT ON COLUMN staging.protected_area.iucn_category IS 'IUCN management category as delivered (IUCN_KAT).';
COMMENT ON COLUMN staging.protected_area.designated IS 'Date of the legal designation (LEG_DATE); NULL when missing or unreadable.';
COMMENT ON COLUMN staging.protected_area.legal_title IS 'Title of the legal act that designates the area (LEG_TITEL).';
COMMENT ON COLUMN staging.protected_area.geom IS 'Outline in EPSG:25832, repaired when it was invalid; NULL when the delivery had none.';
COMMENT ON VIEW staging.protected_area_current IS 'The current version of every protected area.';

-- staging: parcels
COMMENT ON COLUMN staging.parcel.parcel_id IS 'Identifier of this version of the parcel.';
COMMENT ON COLUMN staging.parcel.source_id IS 'The cadastre export the parcel comes from.';
COMMENT ON COLUMN staging.parcel.valid_from_version_id IS 'The snapshot from which this version of the parcel holds.';
COMMENT ON COLUMN staging.parcel.valid_to_version_id IS 'The snapshot that changed or removed the parcel; NULL while this version is current.';
COMMENT ON COLUMN staging.parcel.state_key IS 'Two-digit state key as delivered (05 NRW, 02 Hamburg).';
COMMENT ON COLUMN staging.parcel.district IS 'Name of the district (NRW only; NULL for Hamburg).';
COMMENT ON COLUMN staging.parcel.municipality IS 'Name of the municipality (NRW only; NULL for Hamburg).';
COMMENT ON COLUMN staging.parcel.municipality_key IS 'Municipality key as delivered.';
COMMENT ON COLUMN staging.parcel.cadastral_district IS 'Name of the cadastral district (Gemarkung; NRW only).';
COMMENT ON COLUMN staging.parcel.cadastral_district_key IS 'Number of the cadastral district (Gemarkung).';
COMMENT ON COLUMN staging.parcel.field IS 'Number of the cadastral field (Flur) within the district (NRW only).';
COMMENT ON COLUMN staging.parcel.number_numerator IS 'Parcel number, the part before the slash (Zaehler).';
COMMENT ON COLUMN staging.parcel.number_denominator IS 'Parcel number, the part after the slash (Nenner); NULL when the number has none.';
COMMENT ON COLUMN staging.parcel.location_text IS 'Street or place name of the parcel as delivered (NRW only).';
COMMENT ON COLUMN staging.parcel.updated IS 'Date of the last update of the parcel in the register; NULL when missing or unreadable.';
COMMENT ON COLUMN staging.parcel.geom IS 'Outline in EPSG:25832, repaired when it was invalid; NULL when the delivery had none.';
COMMENT ON VIEW staging.parcel_current IS 'The current version of every parcel.';

-- staging: administrative areas
COMMENT ON COLUMN staging.admin_area.admin_area_id IS 'Identifier of this version of the polygon.';
COMMENT ON COLUMN staging.admin_area.source_id IS 'The VG250 release the polygon comes from.';
COMMENT ON COLUMN staging.admin_area.valid_from_version_id IS 'The snapshot from which this version of the polygon holds.';
COMMENT ON COLUMN staging.admin_area.valid_to_version_id IS 'The snapshot that changed or removed the polygon; NULL while this version is current.';
COMMENT ON COLUMN staging.admin_area.level IS 'municipality or district.';
COMMENT ON COLUMN staging.admin_area.regional_key IS 'Regional key (ARS) as delivered: 12 digits for a municipality, 5 for a district.';
COMMENT ON COLUMN staging.admin_area.name IS 'Name of the area (GEN).';
COMMENT ON COLUMN staging.admin_area.designation IS 'Kind of area as the publisher names it (BEZ), for example Stadt, Gemeinde or Kreis.';
COMMENT ON COLUMN staging.admin_area.state_key IS 'Two-digit state key (SN_L).';
COMMENT ON COLUMN staging.admin_area.geom IS 'Outline in EPSG:25832, repaired when it was invalid; NULL when the delivery had none.';
COMMENT ON VIEW staging.admin_area_current IS 'The current version of every municipality and district polygon.';

-- staging: terrain tiles
COMMENT ON COLUMN staging.terrain_tile.tile_id IS 'Identifier of the catalogued tile file.';
COMMENT ON COLUMN staging.terrain_tile.source_id IS 'The terrain model the tile belongs to.';
COMMENT ON COLUMN staging.terrain_tile.name IS 'File name of the tile.';
COMMENT ON COLUMN staging.terrain_tile.file_sha256 IS 'SHA-256 of the tile file; a replaced file is a new row.';
COMMENT ON COLUMN staging.terrain_tile.file_size IS 'Size of the tile file in bytes.';
COMMENT ON COLUMN staging.terrain_tile.epsg IS 'EPSG code of the coordinate system in the header; NULL when the header names none.';
COMMENT ON COLUMN staging.terrain_tile.width_px IS 'Width of the tile in pixels.';
COMMENT ON COLUMN staging.terrain_tile.height_px IS 'Height of the tile in pixels.';
COMMENT ON COLUMN staging.terrain_tile.pixel_x IS 'Width of one pixel in units of the coordinate system (metres for EPSG:25832).';
COMMENT ON COLUMN staging.terrain_tile.pixel_y IS 'Height of one pixel in units of the coordinate system (metres for EPSG:25832).';
COMMENT ON COLUMN staging.terrain_tile.x_min IS 'Western edge of the tile in its coordinate system.';
COMMENT ON COLUMN staging.terrain_tile.y_min IS 'Southern edge of the tile in its coordinate system.';
COMMENT ON COLUMN staging.terrain_tile.x_max IS 'Eastern edge of the tile in its coordinate system.';
COMMENT ON COLUMN staging.terrain_tile.y_max IS 'Northern edge of the tile in its coordinate system.';
COMMENT ON COLUMN staging.terrain_tile.bits_per_sample IS 'Bits per pixel value (TIFF tag 258), 32 for the float elevation models.';
COMMENT ON COLUMN staging.terrain_tile.sample_format IS 'TIFF tag 339: 1 unsigned integer, 2 signed integer, 3 floating point.';
COMMENT ON COLUMN staging.terrain_tile.compression IS 'TIFF tag 259: 1 none, 5 LZW, 8 Deflate, ...';
COMMENT ON COLUMN staging.terrain_tile.nodata IS 'The no-data value of the tile as written in its header (GDAL_NODATA); NULL when it has none.';
COMMENT ON COLUMN staging.terrain_tile.catalogued_at IS 'When the tile was catalogued.';
COMMENT ON VIEW staging.terrain_tile_current IS 'The tiles of the set that was catalogued last.';

-- staging: validation
COMMENT ON COLUMN staging.snapshot_validation.version_id IS 'The snapshot that was judged.';
COMMENT ON COLUMN staging.snapshot_validation.source_id IS 'The source of the snapshot.';
COMMENT ON COLUMN staging.snapshot_validation.outcome IS 'passed, or quarantined when an error rule fired; a quarantined snapshot is never used by the core.';
COMMENT ON COLUMN staging.snapshot_validation.errors IS 'Number of error findings.';
COMMENT ON COLUMN staging.snapshot_validation.warnings IS 'Number of warning findings.';
COMMENT ON COLUMN staging.snapshot_validation.validated_at IS 'When the snapshot was judged.';
COMMENT ON COLUMN staging.validation_finding.finding_id IS 'Identifier of the finding.';
COMMENT ON COLUMN staging.validation_finding.version_id IS 'The snapshot the finding is about.';
COMMENT ON COLUMN staging.validation_finding.rule IS 'Name of the rule that fired, for example coordinate_missing or voltage_hint_line.';
COMMENT ON COLUMN staging.validation_finding.severity IS 'info, warning or error; an error quarantines the snapshot.';
COMMENT ON COLUMN staging.validation_finding.feature_id IS 'The OSM power object the finding is about; NULL for a finding about the whole snapshot.';
COMMENT ON COLUMN staging.validation_finding.detail IS 'The numbers behind the finding (counts, shares, hint voltage, distance in metres).';
COMMENT ON COLUMN staging.substation_review.source_id IS 'The OSM extract of the substation.';
COMMENT ON COLUMN staging.substation_review.feature_id IS 'The version of the substation in staging.osm_power_feature that holds at the newest validated snapshot.';
COMMENT ON COLUMN staging.substation_review.lon IS 'Longitude of the location, degrees east (EPSG:4326).';
COMMENT ON COLUMN staging.substation_review.lat IS 'Latitude of the location, degrees north (EPSG:4326).';
COMMENT ON COLUMN staging.substation_review.line_hint_v IS 'Highest voltage in volts of the power lines near the substation; NULL when none is near.';
COMMENT ON COLUMN staging.substation_review.line_hint_distance_m IS 'Distance in metres to the nearest of those lines.';
COMMENT ON COLUMN staging.substation_review.line_osm_key IS 'OSM key of a line behind line_hint_v.';
COMMENT ON COLUMN staging.substation_review.type_hint_class IS 'What the substation tag suggests: high_plus or medium_low; NULL when it suggests nothing.';
COMMENT ON COLUMN staging.substation_review.conflict IS 'True when the hints disagree with each other.';
COMMENT ON COLUMN staging.substation_review.suggestion IS 'conflict, hv_candidate, likely_low_voltage or no_evidence; a suggestion only, never a decision.';

-- core: rules, decisions and builds of the substations
COMMENT ON COLUMN core.rule_set.rule_set_id IS 'Identifier of the rule set.';
COMMENT ON COLUMN core.rule_set.version IS 'Version of the rules (major.minor.patch); unique.';
COMMENT ON COLUMN core.rule_set.parameters IS 'Every parameter of the rules except the version: sources, states, voltages, distances in metres, audit settings.';
COMMENT ON COLUMN core.rule_set.created_at IS 'When the version was first used.';
COMMENT ON COLUMN core.review_decision.decision_id IS 'Identifier of the decision.';
COMMENT ON COLUMN core.review_decision.source_id IS 'The OSM extract of the substation.';
COMMENT ON COLUMN core.review_decision.layer IS 'GDAL layer of the substation: points, lines or multipolygons.';
COMMENT ON COLUMN core.review_decision.osm_key IS 'n<id>, w<id> or r<id> of the substation; a decision follows the object across snapshots.';
COMMENT ON COLUMN core.review_decision.decision IS 'high_voltage, not_high_voltage or not_a_substation.';
COMMENT ON COLUMN core.review_decision.reason IS 'Why the person decided so, in words.';
COMMENT ON COLUMN core.review_decision.reviewer IS 'Who decided.';
COMMENT ON COLUMN core.review_decision.evidence IS 'What the person looked at (imagery, operator data, links).';
COMMENT ON COLUMN core.review_decision.rule_set_id IS 'The rule set that was current when the decision was made.';
COMMENT ON COLUMN core.review_decision.supersedes_decision_id IS 'The decision this one replaces; NULL for the first decision about the substation.';
COMMENT ON COLUMN core.review_decision.decided_at IS 'When the decision was recorded.';
COMMENT ON VIEW core.review_decision_current IS 'The newest decision about every substation that has one.';
COMMENT ON COLUMN core.build.build_id IS 'Identifier of the substation build.';
COMMENT ON COLUMN core.build.rule_set_id IS 'The rule set the build used.';
COMMENT ON COLUMN core.build.source_versions IS 'The snapshot of every input the build read, by source.';
COMMENT ON COLUMN core.build.decisions_through IS 'The newest decision the build took into account; later decisions are not in it.';
COMMENT ON COLUMN core.build.counts IS 'Summary counts of the build: substations per scenario, tier and voltage source.';
COMMENT ON COLUMN core.build.content_hash IS 'SHA-256 over the content of the build without database-generated numbers; a rebuild must give the same hash.';
COMMENT ON COLUMN core.build.created_at IS 'When the build was made.';

-- core: substations
COMMENT ON COLUMN core.substation.build_id IS 'The build the row belongs to.';
COMMENT ON COLUMN core.substation.source_id IS 'The OSM extract of the substation.';
COMMENT ON COLUMN core.substation.layer IS 'GDAL layer of the substation: points, lines or multipolygons.';
COMMENT ON COLUMN core.substation.osm_key IS 'n<id>, w<id> or r<id> of the substation.';
COMMENT ON COLUMN core.substation.feature_id IS 'The version of the object in staging.osm_power_feature that the build read.';
COMMENT ON COLUMN core.substation.name IS 'OSM tag name.';
COMMENT ON COLUMN core.substation.operator IS 'OSM tag operator.';
COMMENT ON COLUMN core.substation.substation_type IS 'OSM tag substation.';
COMMENT ON COLUMN core.substation.voltage_v IS 'Highest voltage in volts, from the tag; NULL when the tag has none.';
COMMENT ON COLUMN core.substation.voltage_source IS 'What settles the voltage: tag, decision (of a person) or none.';
COMMENT ON COLUMN core.substation.hint IS 'Suggestion of the validation for an untagged voltage: hv_candidate, conflict, likely_low_voltage or no_evidence.';
COMMENT ON COLUMN core.substation.decision IS 'The current decision of a person about the substation; NULL when there is none.';
COMMENT ON COLUMN core.substation.decision_id IS 'The decision behind decision.';
COMMENT ON COLUMN core.substation.in_strict IS 'In the strict scenario: a voltage tag at or above the high-voltage limit of the rules, or a person decided high_voltage.';
COMMENT ON COLUMN core.substation.in_likely IS 'In the likely scenario: strict, plus untagged substations whose hints point to high voltage.';
COMMENT ON COLUMN core.substation.in_inclusive IS 'In the inclusive scenario: likely, plus every substation whose voltage is unknown.';
COMMENT ON COLUMN core.substation.reason IS 'Why the substation is in its scenarios: decision_high, decision_not_high, decision_not_a_substation, tag_high, tag_low, hint_candidate, hint_conflict, hint_low or unknown.';
COMMENT ON COLUMN core.substation.wind_units_in_reach IS 'Number of usable wind units within the reach distance of the rules (straight line).';
COMMENT ON COLUMN core.substation.impact IS 'Of those, the units for which this substation is closer than their nearest strict substation; 0 means no decision about it can change a route.';
COMMENT ON COLUMN core.substation.audit_sample IS 'Drawn for the audit by a fixed hash: an untagged substation with a hint and a wind unit within reach.';
COMMENT ON COLUMN core.substation.location IS 'A point on the substation in EPSG:25832.';
COMMENT ON VIEW core.substation_current IS 'The substations of the newest build.';
COMMENT ON COLUMN core.substation_current.build_id IS 'The build the row belongs to: always the newest one.';
COMMENT ON COLUMN core.review_queue.osm_key IS 'n<id>, w<id> or r<id> of the substation.';
COMMENT ON COLUMN core.review_queue.lon IS 'Longitude of the location, degrees east (EPSG:4326).';
COMMENT ON COLUMN core.review_queue.lat IS 'Latitude of the location, degrees north (EPSG:4326).';

-- core: wind units
COMMENT ON COLUMN core.wind_build.wind_build_id IS 'Identifier of the wind unit build.';
COMMENT ON COLUMN core.wind_build.rules_version IS 'The version of the rules the build used; its parameters are in core.wind_rule_set.';
COMMENT ON COLUMN core.wind_build.source_versions IS 'The snapshot of every input the build read, by source.';
COMMENT ON COLUMN core.wind_build.counts IS 'Summary counts of the build: units per scenario, position class and status group, OSM turbines.';
COMMENT ON COLUMN core.wind_build.content_hash IS 'SHA-256 over the content of the build without database-generated numbers; a rebuild must give the same hash.';
COMMENT ON COLUMN core.wind_build.created_at IS 'When the build was made.';
COMMENT ON COLUMN core.wind_unit.wind_build_id IS 'The build the row belongs to.';
COMMENT ON COLUMN core.wind_unit.source_id IS 'The register export of the unit.';
COMMENT ON COLUMN core.wind_unit.unit_key IS 'MaStR number of the unit.';
COMMENT ON COLUMN core.wind_unit.unit_id IS 'The version of the unit in staging.wind_unit that the build read.';
COMMENT ON COLUMN core.wind_unit.state_key IS 'First two digits of the registered municipality key.';
COMMENT ON COLUMN core.wind_unit.status IS 'Operating status as registered.';
COMMENT ON COLUMN core.wind_unit.status_group IS 'existing (in operation or temporarily shut down), planned or retired.';
COMMENT ON COLUMN core.wind_unit.name IS 'Name of the unit as registered.';
COMMENT ON COLUMN core.wind_unit.wind_farm IS 'Name of the wind farm as registered.';
COMMENT ON COLUMN core.wind_unit.grid_location_key IS 'MaStR number of the location: the units of one wind farm share it.';
COMMENT ON COLUMN core.wind_unit.municipality_key IS 'Municipality key (AGS) as registered.';
COMMENT ON COLUMN core.wind_unit.municipality IS 'Name of the municipality as registered.';
COMMENT ON COLUMN core.wind_unit.place_key IS 'AGS of the municipality whose boundary covers the position (land before water); NULL without a position or a covering boundary.';
COMMENT ON COLUMN core.wind_unit.gross_kw IS 'Gross rated power in kilowatts.';
COMMENT ON COLUMN core.wind_unit.hub_height_m IS 'Hub height in metres.';
COMMENT ON COLUMN core.wind_unit.rotor_diameter_m IS 'Rotor diameter in metres.';
COMMENT ON COLUMN core.wind_unit.commissioned IS 'Date of commissioning.';
COMMENT ON COLUMN core.wind_unit.qa_flags IS 'The findings of staging.wind_unit, carried over.';
COMMENT ON COLUMN core.wind_unit.reason IS 'Why the unit has its class: osm_turbine, register_only, far_from_municipality, isolated_in_farm, far_from_municipality_and_isolated_in_farm, coordinate_flagged, no_coordinate or retired.';
COMMENT ON COLUMN core.wind_unit.osm_source_id IS 'The OSM extract of the nearest turbine within the match distance; NULL when there is none.';
COMMENT ON COLUMN core.wind_unit.osm_key IS 'n<id>, w<id> or r<id> of that turbine.';
COMMENT ON COLUMN core.wind_unit.osm_distance_m IS 'Distance in metres from the registered position to that turbine.';
COMMENT ON COLUMN core.wind_unit.in_strict IS 'In the strict scenario: an existing unit with a confirmed or plausible position.';
COMMENT ON COLUMN core.wind_unit.in_likely IS 'In the likely scenario: strict, plus planned units with such a position.';
COMMENT ON COLUMN core.wind_unit.in_inclusive IS 'In the inclusive scenario: likely, plus existing or planned units with a doubtful position.';
COMMENT ON COLUMN core.wind_unit.geom IS 'The registered position in EPSG:25832, never moved; NULL when the register has none.';
COMMENT ON VIEW core.wind_unit_current IS 'The wind units of the newest build.';
COMMENT ON COLUMN core.wind_unit_current.wind_build_id IS 'The build the row belongs to: always the newest one.';

-- functions
COMMENT ON FUNCTION core.refuse_change() IS 'Trigger function that refuses UPDATE, DELETE and TRUNCATE on an append-only table.';
COMMENT ON FUNCTION core.check_decision_chain() IS 'Trigger function: a decision about a substation must replace the newest one, or be the first.';
COMMENT ON FUNCTION staging.osm_tag(text, text) IS 'The value of one key in a GDAL hstore text of OSM tags; NULL when the key is missing.';
COMMENT ON FUNCTION staging.parse_voltage_v(text) IS 'The highest whole number in volts of a voltage tag such as 380000;110000; NULL when there is none.';
COMMENT ON FUNCTION staging.parse_output_w(text) IS 'Electrical output in watts of a tag such as 3 MW, 600 kW or 2,4 MW; NULL for anything else.';
COMMENT ON FUNCTION staging.power_kind(text, text, text) IS 'The kind of an OSM power object from its tags power, generator:source and generator:method.';
COMMENT ON FUNCTION staging.voltage_class(text, integer) IS 'extra_high, high, medium_low or unknown for substations, lines and cables; NULL for other kinds.';
COMMENT ON FUNCTION staging.parse_number(text) IS 'A number from text such as 2000.000; NULL for anything else.';
COMMENT ON FUNCTION staging.parse_date(text) IS 'A date from text that starts with YYYY-MM-DD; NULL for anything else, an impossible date included.';
COMMENT ON FUNCTION staging.osm_power_as_of(text, bigint) IS 'The OSM power objects of a source as they were when the given snapshot had just been applied.';
COMMENT ON FUNCTION staging.wind_unit_as_of(text, bigint) IS 'The wind units of a source as they were when the given snapshot had just been applied.';
COMMENT ON FUNCTION staging.land_cover_as_of(text, bigint) IS 'The land-cover polygons of a source as they were when the given snapshot had just been applied.';
COMMENT ON FUNCTION staging.protected_area_as_of(text, bigint) IS 'The protected areas of a source as they were when the given snapshot had just been applied.';
COMMENT ON FUNCTION staging.parcel_as_of(text, bigint) IS 'The parcels of a source as they were when the given snapshot had just been applied.';
COMMENT ON FUNCTION staging.admin_area_as_of(text, bigint) IS 'The administrative areas of a source as they were when the given snapshot had just been applied.';
